CREATE VIEW dbo.IV_Q$ACOMPANHAMENTO_VENDA ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario,  DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao,  SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , MODELO_D_EQUIPAME, VALOR, TIPO_DE_FINANCIAME, AGENCIA, NOME_DO_GERENTE, TELEFONE_DA_AGENCI, PROPOSTA_ENTREGUE_, PROPOSTA_PROTOCOLA, PROCESSO_MONTADO, PROCESSO_EM_ANALIS, PROCESSO_APROVADO, PROCESSO_NAO_APROV, CONTRATO_EMITIDO, CONTRATO_REGISTRAD, PAC_EMITIDO, FATURAMENTO_REALIZ, N__PEDIDO_NA_FABRI, TIPO_DE_MAQUINA, PROB_APROVACAO, DTA_PREVFAT, ORIGEM_FATURAMENTO, MARCA_EQUIPAMENTO, VALOR_SINAL, VLR_FINANCIADO, NRO_PEDIDO, NRO_CHASSI, INST_FINANCEIRA, VLR_REC_PROPRIO, NRO_CONTRATO, NRO_PAC, EMAIL_CONTATO, DESC_IMPLEMENTO, NRO_NF, NRO_AGENCIA, TIPO_IMPLEMENTO, QTD_PESO_DIANTEIRO_, QTD_PESO_TRASEIRO_, LASTRO_LIQUIDO_DIANT, LASTRO_LIQUIDO_TRAS_, RODADO_DIANT__, RODADO_TRAS__, OUTRAS_CONFIGURACOES, INFORMACOES_PARA_O_F, TESTE)     AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO,  QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS,  QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO,  QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.MODELO_D_EQUIPAME, TABF.VALOR, TABF.TIPO_DE_FINANCIAME, TABF.AGENCIA, TABF.NOME_DO_GERENTE, TABF.TELEFONE_DA_AGENCI, TABF.PROPOSTA_ENTREGUE_, TABF.PROPOSTA_PROTOCOLA, TABF.PROCESSO_MONTADO, TABF.PROCESSO_EM_ANALIS, TABF.PROCESSO_APROVADO, TABF.PROCESSO_NAO_APROV, TABF.CONTRATO_EMITIDO, TABF.CONTRATO_REGISTRAD, TABF.PAC_EMITIDO, TABF.FATURAMENTO_REALIZ, TABF.N__PEDIDO_NA_FABRI, TABF.TIPO_DE_MAQUINA, TABF.PROB_APROVACAO, TABF.DTA_PREVFAT, TABF.ORIGEM_FATURAMENTO, TABF.MARCA_EQUIPAMENTO, TABF.VALOR_SINAL, TABF.VLR_FINANCIADO, TABF.NRO_PEDIDO, TABF.NRO_CHASSI, TABF.INST_FINANCEIRA, TABF.VLR_REC_PROPRIO, TABF.NRO_CONTRATO, TABF.NRO_PAC, TABF.EMAIL_CONTATO, TABF.DESC_IMPLEMENTO, TABF.NRO_NF, TABF.NRO_AGENCIA, TABF.TIPO_IMPLEMENTO, TABF.QTD_PESO_DIANTEIRO_, TABF.QTD_PESO_TRASEIRO_, TABF.LASTRO_LIQUIDO_DIANT, TABF.LASTRO_LIQUIDO_TRAS_, TABF.RODADO_DIANT__, TABF.RODADO_TRAS__, TABF.OUTRAS_CONFIGURACOES, TABF.INFORMACOES_PARA_O_F, TABF.TESTE    FROM IV_Q_ACOMPANHAMENTO_VENDA TABF  	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO  	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO  	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA 